470	@@ -0,0 +1,66 @@
471	+using Microsoft.EntityFrameworkCore;
472	+using seed_b_backend.Api.Data;
473	+using seed_b_backend.Api.Dtos;
474	+
475	+namespace seed_b_backend.Api.Services;
476	+
477	+public class ProductService(AppDbContext db)
478	+{
479	+    public async Task<ProductDetailDto?> GetProductDetailAsync(string id)
480	+    {
481	+        var rowsAffected = await db.Products
482	+            .Where(p => p.Id == id)
483	+            .ExecuteUpdateAsync(s => s.SetProperty(p => p.ViewCount, p => p.ViewCount + 1));
484	+
485	+        if (rowsAffected == 0)
486	+        {
487	+            return null; // Produkt existiert nicht -> Controller mappt auf 404, kein Increment fand statt
488	+        }
489	+
490	+        var product = await db.Products
491	+            .Include(p => p.Subcategory!)
492	+                .ThenInclude(s => s!.Category)
493	+            .Include(p => p.Offers)
494	+                .ThenInclude(o => o.Supplier)
495	+            .FirstOrDefaultAsync(p => p.Id == id);
496	+
497	+        if (product is null)
498	+        {
499	+            return null;
500	+        }
501	+
502	+        var attributes = (product.Subcategory?.AttributeNames ?? [])
503	+            .Select(name => new { name, value = ProductAttributeJson.TryFormatValue(product.Attributes, name) })
504	+            .Where(a => a.value is not null)
505	+            .Select(a => new ProductAttributeDto(a.name, a.value!))
506	+            .ToList();
507	+
508	+        var ratingValues = await db.Ratings
509	+            .Where(r => r.ProductId == id)
510	+            .Select(r => r.Value)
511	+            .ToListAsync();
512	+
513	+        double? averageRating = ratingValues.Count == 0
514	+            ? null
515	+            : Math.Round(ratingValues.Average(), 1, MidpointRounding.AwayFromZero);
516	+
517	+        var offers = product.Offers
518	+            .OrderBy(o => o.Price)
519	+            .ThenBy(o => o.SupplierId)
520	+            .Select(o => new ProductOfferDto(o.SupplierId, o.Supplier!.Name, o.Price))
521	+            .ToList();
522	+
523	+        return new ProductDetailDto(
524	+            product.Id,
525	+            product.Name,
526	+            product.Description,
527	+            product.Subcategory!.CategoryId,
528	+            product.Subcategory.Category!.Name,
529	+            product.SubcategoryId,
530	+            product.Subcategory.Name,
531	+            attributes,
532	+            averageRating,
533	+            ratingValues.Count,
534	+            offers);
535	+    }
536	+}
