+    fixture.detectChanges();
+
+    paramMap.next(convertToParamMap({ id: 'P1' }));
+    fixture.detectChanges();
+    paramMap.next(convertToParamMap({ id: 'P2' }));
+    fixture.detectChanges();
+
+    expect(getProduct).toHaveBeenNthCalledWith(1, 'P1');
